const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const session_id = Number(input.session_id);
const message_id = Number(input.message_id);
const context_message_limit = Number(input.context_message_limit ?? 20);
const model_provider = text(input.model_provider || 'openai').toLowerCase();
const model_name = text(input.model_name || 'gpt-5-mini');
const prompt_version = text(input.prompt_version || 'intent-router-final-v5');
const confirm_analysis = toBoolean(input.confirm_analysis);

const errors = [];

if (!Number.isInteger(session_id) || session_id < 1) {
  errors.push({
    field: 'session_id',
    message: 'session_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!Number.isInteger(message_id) || message_id < 1) {
  errors.push({
    field: 'message_id',
    message: 'message_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (
  !Number.isInteger(context_message_limit) ||
  context_message_limit < 1 ||
  context_message_limit > 100
) {
  errors.push({
    field: 'context_message_limit',
    message: 'تعداد پیام‌های زمینه باید بین 1 و 100 باشد.',
  });
}

if (!model_provider) {
  errors.push({
    field: 'model_provider',
    message: 'نام ارائه‌دهنده مدل الزامی است.',
  });
}

if (!model_name) {
  errors.push({
    field: 'model_name',
    message: 'نام مدل الزامی است.',
  });
}

if (!prompt_version) {
  errors.push({
    field: 'prompt_version',
    message: 'نسخه پرامپت الزامی است.',
  });
}

if (confirm_analysis !== true) {
  errors.push({
    field: 'confirm_analysis',
    message: 'تحلیل پیام باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    session_id,
    message_id,
    context_message_limit,
    model_provider,
    model_name,
    prompt_version,
    analysis_started_at_ms: Date.now(),
    confirm_analysis,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{ json: $json }];
}

const input = $('Normalize and Validate AI Analysis').first().json;
const session = $json.session_context || {};
const target = $json.target_message || {};
const messages = Array.isArray($json.recent_messages)
  ? $json.recent_messages
  : [];

const aiPrompt = [
  'CURRENT_MESSAGE:',
  JSON.stringify({
    message_id: target.message_id,
    text: target.content_text,
    payload: target.content_json,
    message_type: target.message_type,
  }),
  '',
  'CONVERSATION_STATE:',
  JSON.stringify({
    clinic_name: session.clinic_name,
    patient_name: session.patient_name,
    mobile: session.mobile,
    language: session.language,
    last_intent: session.last_intent,
    pending_action: session.pending_action,
    collected_entities: session.collected_entities || {},
    existing_risk_flags: session.session_risk_flags || [],
    context_summary: session.context_summary || null,
  }),
  '',
  'RECENT_MESSAGES:',
  JSON.stringify(messages),
  '',
  'Return only the structured result required by the output schema.',
].join('\n');

return [{
  json: {
    ...$json,
    model_provider: input.model_provider,
    model_name: input.model_name,
    prompt_version: input.prompt_version,
    analysis_started_at_ms: input.analysis_started_at_ms,
    ai_prompt: aiPrompt,
  },
}];

const envelope = $json ?? {};
let parsed = envelope.output ?? envelope;

if (typeof parsed === 'string') {
  try {
    parsed = JSON.parse(parsed);
  } catch {
    const match = parsed.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
    } else {
      throw new Error('AI output is not valid JSON.');
    }
  }
}

if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.output &&
  typeof parsed.output === 'object'
) {
  parsed = parsed.output;
}

const context = $('Build AI Router Prompt').first().json;
const session = context.session_context || {};
const target = context.target_message || {};

const riskFlags = Array.isArray(parsed.risk_flags)
  ? [...new Set(parsed.risk_flags.filter(Boolean))]
  : [];

const filteredRiskFlags =
  riskFlags.length > 1
    ? riskFlags.filter((item) => item !== 'none')
    : riskFlags;

const entities =
  parsed.entities &&
  typeof parsed.entities === 'object' &&
  !Array.isArray(parsed.entities)
    ? parsed.entities
    : {};

const missingFields = Array.isArray(parsed.missing_fields)
  ? [...new Set(parsed.missing_fields.filter(Boolean))]
  : [];

const confidence = Math.max(
  0,
  Math.min(1, Number(parsed.confidence ?? 0))
);

const urgent =
  parsed.intent === 'emergency' ||
  parsed.tool_action === 'urgent_human_handoff';

return [{
  json: {
    success: true,
    result: urgent
      ? 'urgent_ai_route_created'
      : 'ai_route_created',

    session_id: Number(session.session_id),
    message_id: Number(target.message_id),

    intent: parsed.intent,
    confidence,
    language: parsed.language || session.language || 'unknown',
    entities,
    entities_json: JSON.stringify(entities),
    missing_fields: missingFields,
    missing_fields_json: JSON.stringify(missingFields),
    risk_flags: filteredRiskFlags,
    risk_flags_json: JSON.stringify(filteredRiskFlags),
    requires_human: Boolean(parsed.requires_human || urgent),
    requires_confirmation: Boolean(parsed.requires_confirmation),
    tool_action: urgent
      ? 'urgent_human_handoff'
      : parsed.tool_action,
    next_question: parsed.next_question ?? null,
    reasoning_summary: String(parsed.reasoning_summary || '').slice(0, 1000),

    model_provider: context.model_provider,
    model_name: context.model_name,
    prompt_version: context.prompt_version,
    raw_output_json: JSON.stringify(envelope),
    parsed_output_json: JSON.stringify(parsed),
    latency_ms: Math.max(
      0,
      Date.now() - Number(context.analysis_started_at_ms || Date.now())
    ),
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات تحلیل مدل زبانی ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];

return [{
  json: {
    success: false,
    result: $json.result || 'ai_context_not_available',
    message:
      $json.result === 'conversation_session_not_found'
        ? 'جلسه مکالمه پیدا نشد.'
        : 'پیام ورودی در جلسه مکالمه پیدا نشد.',
  },
}];

const context = $json || {};
const session = context.session_context || {};
const target = context.target_message || {};

const originalText = String(
  target.content_text || ''
).trim();

const lower = originalText.toLowerCase();

const includesAny = (terms) =>
  terms.some((term) => lower.includes(term));

const firstMatch = (pattern) => {
  const match = originalText.match(pattern);
  return match ? String(match[1] || '').trim() : '';
};

const isoDate = firstMatch(
  /(?:date|تاریخ)\s*[:=]\s*(\d{4}-\d{2}-\d{2})/i
) || firstMatch(/(\d{4}-\d{2}-\d{2})/);

const timeValue = firstMatch(
  /(?:time|ساعت)\s*[:=]\s*([0-2]\d:[0-5]\d)/i
) || firstMatch(/\b([0-2]\d:[0-5]\d)\b/);

const appointmentIdText =
  firstMatch(
    /(?:appointment_id|appointment|نوبت)\s*[:=#]?\s*(\d+)/i
  );

const doctorName =
  firstMatch(
    /doctor\s*[:=]\s*([^;\n]+)/i
  ) ||
  (
    originalText.includes('دکتر تست')
      ? 'دکتر تست'
      : ''
  );

const serviceName =
  firstMatch(
    /service\s*[:=]\s*([^;\n]+)/i
  ) ||
  (
    originalText.includes('ویزیت تست')
      ? 'ویزیت تست'
      : ''
  );

const patientName =
  session.patient_name ||
  firstMatch(
    /patient\s*[:=]\s*([^;\n]+)/i
  );

const mobile =
  session.mobile ||
  firstMatch(
    /(?:mobile|موبایل)\s*[:=]\s*(\+?[0-9]{8,15})/i
  );

let intent = 'unclear';
let confidence = 0.45;
let tool_action = 'none';
let requires_human = false;
let requires_confirmation = false;
let next_question =
  'لطفاً درخواست خود را با جزئیات بیشتری توضیح دهید.';
let risk_flags = [];
let missing_fields = [];
let entities = {};

if (
  includesAny([
    'تنگی نفس',
    'نفس نمی',
    'درد قفسه سینه',
    'خونریزی شدید',
    'بیهوش',
    'تشنج',
    'اوردوز',
    'خودکشی',
    'chest pain',
    'breathing difficulty',
    'severe bleeding',
    'overdose',
    'suicide',
  ])
) {
  intent = 'emergency';
  confidence = 0.99;
  tool_action = 'urgent_human_handoff';
  requires_human = true;
  next_question = null;

  if (
    includesAny([
      'تنگی نفس',
      'نفس نمی',
      'breathing difficulty',
    ])
  ) {
    risk_flags.push('breathing_difficulty');
  }

  if (
    includesAny([
      'درد قفسه سینه',
      'chest pain',
    ])
  ) {
    risk_flags.push('chest_pain');
  }

  if (
    includesAny([
      'خونریزی شدید',
      'severe bleeding',
    ])
  ) {
    risk_flags.push('severe_bleeding');
  }

  if (
    includesAny([
      'اوردوز',
      'overdose',
    ])
  ) {
    risk_flags.push('possible_overdose');
  }

  if (
    includesAny([
      'بیهوش',
      'unconscious',
    ])
  ) {
    risk_flags.push('loss_of_consciousness');
  }

  if (
    includesAny([
      'تشنج',
      'seizure',
    ])
  ) {
    risk_flags.push('seizure');
  }

  if (
    includesAny([
      'خودکشی',
      'suicide',
    ])
  ) {
    risk_flags.push('self_harm_or_violence');
  }

} else if (
  includesAny([
    'ساعت کاری',
    'زمان کاری',
    'آدرس',
    'لوکیشن',
    'قیمت',
    'هزینه',
    'بیمه',
    'working hours',
    'address',
    'price',
  ])
) {
  intent = 'clinic_information';
  confidence = 0.98;
  tool_action = 'ask_clinic_information';
  next_question = null;

  entities = {
    category_hint:
      includesAny(['ساعت کاری', 'زمان کاری', 'working hours'])
        ? 'working_hours'
        : includesAny(['آدرس', 'لوکیشن', 'address'])
          ? 'location'
          : includesAny(['قیمت', 'هزینه', 'price'])
            ? 'pricing'
            : includesAny(['بیمه'])
              ? 'insurance'
              : 'all',
  };

} else if (
  includesAny([
    'نوبت‌های من',
    'نوبت های من',
    'قرارهای من',
    'my appointments',
  ])
) {
  intent = 'appointment_lookup';
  confidence = 0.98;
  tool_action = 'find_patient_appointments';
  next_question = null;
  entities = { mobile };

} else if (
  includesAny([
    'وقت آزاد',
    'زمان آزاد',
    'نوبت آزاد',
    'available slot',
    'available time',
  ])
) {
  intent = 'appointment_availability';
  confidence = 0.95;
  tool_action = 'find_available_slots';
  next_question = null;

  entities = {
    doctor_name: doctorName,
    service_name: serviceName,
    target_date: isoDate,
  };

  if (!doctorName) {
    missing_fields.push('doctor_name');
  }

  if (!serviceName) {
    missing_fields.push('service_name');
  }

  if (!isoDate) {
    missing_fields.push('target_date');
  }

  if (missing_fields.length) {
    next_question =
      'نام پزشک، نوع خدمت و تاریخ موردنظر را ارسال کنید.';
  }

} else if (
  includesAny([
    'ثبت نوبت',
    'رزرو نوبت',
    'نوبت بگیر',
    'book appointment',
  ])
) {
  intent = 'appointment_booking';
  confidence = 0.96;
  tool_action = 'create_appointment';
  requires_confirmation = true;

  entities = {
    doctor_name: doctorName,
    service_name: serviceName,
    patient_name: patientName,
    mobile,
    target_date: isoDate,
    start_time: timeValue,
    visit_reason: originalText,
  };

  for (const [field, value] of Object.entries({
    doctor_name: doctorName,
    service_name: serviceName,
    patient_name: patientName,
    mobile,
    target_date: isoDate,
    start_time: timeValue,
  })) {
    if (!value) {
      missing_fields.push(field);
    }
  }

  next_question = missing_fields.length
    ? 'برای ثبت نوبت، اطلاعات پزشک، خدمت، تاریخ و ساعت را کامل کنید.'
    : 'جزئیات نوبت را بررسی و انجام آن را تأیید کنید.';

} else if (
  includesAny([
    'لغو نوبت',
    'کنسل نوبت',
    'cancel appointment',
  ])
) {
  intent = 'appointment_cancellation';
  confidence = 0.97;
  tool_action = 'cancel_appointment';
  requires_confirmation = true;

  entities = {
    mobile,
    appointment_id:
      appointmentIdText
        ? Number(appointmentIdText)
        : null,
    cancellation_reason: originalText,
  };

  if (!appointmentIdText) {
    missing_fields.push('appointment_id');
    next_question =
      'شناسه نوبتی را که باید لغو شود ارسال کنید.';
  } else {
    next_question =
      'لغو این نوبت را تأیید می‌کنید؟';
  }

} else if (
  includesAny([
    'جابجایی نوبت',
    'جابه‌جایی نوبت',
    'تغییر نوبت',
    'reschedule appointment',
  ])
) {
  intent = 'appointment_reschedule';
  confidence = 0.97;
  tool_action = 'reschedule_appointment';
  requires_confirmation = true;

  entities = {
    mobile,
    appointment_id:
      appointmentIdText
        ? Number(appointmentIdText)
        : null,
    new_target_date: isoDate,
    new_start_time: timeValue,
    reschedule_reason: originalText,
  };

  if (!appointmentIdText) {
    missing_fields.push('appointment_id');
  }

  if (!isoDate) {
    missing_fields.push('new_target_date');
  }

  if (!timeValue) {
    missing_fields.push('new_start_time');
  }

  next_question = missing_fields.length
    ? 'شناسه نوبت و تاریخ و ساعت جدید را ارسال کنید.'
    : 'جابجایی نوبت با این مشخصات را تأیید می‌کنید؟';

} else if (
  includesAny([
    'توقف پیام',
    'لغو پیام',
    'پیام نده',
    'stop',
    'unsubscribe',
  ])
) {
  intent = 'communication_opt_out';
  confidence = 0.99;
  tool_action =
    'process_communication_consent_response';
  next_question = null;

  entities = {
    mobile,
    communication_action: 'auto',
    communication_channel:
      session.channel === 'webchat'
        ? 'sms'
        : session.channel,
  };

} else if (
  includesAny([
    'سلام',
    'hello',
    'hi',
  ])
) {
  intent = 'general_conversation';
  confidence = 0.9;
  tool_action = 'none';
  next_question =
    'سلام. برای نوبت، اطلاعات کلینیک یا پیگیری درخواست چه کمکی نیاز دارید؟';
}

const uniqueRiskFlags = [
  ...new Set(risk_flags),
];

const parsed = {
  intent,
  confidence,
  language:
    session.language ||
    'fa',
  entities,
  missing_fields: [
    ...new Set(missing_fields),
  ],
  risk_flags:
    uniqueRiskFlags.length
      ? uniqueRiskFlags
      : ['none'],
  requires_human,
  requires_confirmation,
  tool_action,
  next_question,
  reasoning_summary:
    'خروجی قطعی Mock Router برای تست بدون Credential.',
};

return [{
  json: {
    output: parsed,
  },
}];
